import json
from pathlib import Path

BATAS = 100


def baca(jalur):
    """Baca berkas pesanan."""
    with open(jalur) as f:
        return json.load(f)


def saring(pesanan, minimal=BATAS):
    hasil = []
    for p in pesanan:
        if p["total"] >= minimal:
            hasil.append(p)
    return hasil


def ringkas(pesanan):
    total = sum(p["total"] for p in pesanan)
    rata = total / max(len(pesanan), 1)
    return {"jumlah": len(pesanan), "rata": round(rata, 2)}


def utama():
    data = baca(Path("pesanan.json"))
    besar = saring(data)
    print(ringkas(besar))


if __name__ == "__main__":
    utama()
